static void find_pio_PCI ( struct get_conf * buf ) { printk ( "eata_dma: kernel PCI support not enabled. Skipping scan for PCI HBAs.\n" ) ; struct pci_dev * dev = NULL ; unsigned long base , x ; while ( ( dev = pci_get_device ( PCI_VENDOR_ID_DPT , PCI_DEVICE_ID_DPT , dev ) ) != NULL ) { DBG ( DBG_PROBE && DBG_PCI , printk ( "eata_pio: find_PCI, HBA at %s\n" , pci_name ( dev ) ) ) ; pci_set_master ( dev ) ; base = pci_resource_flags ( dev , 0 ) ; if ( base & IORESOURCE_MEM ) { printk ( "eata_pio: invalid base address of device %s\n" , pci_name ( dev ) ) ; continue ; } base = pci_resource_start ( dev , 0 ) ; if ( ( inb ( base ) == 0x12 ) && ( inb ( base + 1 ) == 0x14 ) ) { continue ; } base += 0x10 ; if ( base != 0x1f8 ) { if ( get_pio_conf_PIO ( base , buf ) ) { if ( buf -> FORCADR ) { release_region ( base , 9 ) ; continue ; } if ( ! register_pio_HBA ( base , buf , dev ) ) { release_region ( base , 9 ) ; continue ; } if ( base < 0x1000 ) { for ( x = 0 ; x < MAXISA ; ++ x ) { if ( ISAbases [ x ] == base ) { ISAbases [ x ] = 0 ; break ; } } } if ( ( base & 0x0fff ) == 0x0c88 ) { x = ( base >> 12 ) & 0x0f ; EISAbases [ x ] = 0 ; } } if ( check_blink_state ( base ) ) { printk ( "eata_pio: HBA is in BLINK state.\n" "Consult your HBAs manual to correct this.\n" ) ; } } } } 